import { Button } from "@/registry/erbium/ui/button";
import {
  Dialog,
  DialogPanel,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/registry/erbium/ui/dialog";

export default function DialogNoCloseButtonExample() {
  return (
    <Dialog>
      <DialogTrigger render={<Button variant="outline" />}>No Close Button</DialogTrigger>
      <DialogPanel showCloseButton={false}>
        <DialogHeader>
          <DialogTitle>No Close Button</DialogTitle>
          <DialogDescription>
            This dialog doesn&apos;t have a close button in the top-right corner.
          </DialogDescription>
        </DialogHeader>
        <DialogContent>Use the escape key or click outside to close.</DialogContent>
      </DialogPanel>
    </Dialog>
  );
}

import DialogNoCloseButtonExample from "../examples/dialog-no-close-button";

const Example = () => <DialogNoCloseButtonExample />;

export default Example;
